mapper.select:
select at.defense_mode, at.defense_schedule from algorithm_task at inner join algorithm_task_device atd on at.id = atd.task_id where atd.device_id = #{deviceId,jdbcType=VARCHAR} and at.alert_event_enabled = true and at.is_enabled = true
and at.id = #{taskId,jdbcType=INTEGER}
order by at.id asc limit 1

mapper.update:
update alert
set image_url = #{imagePath,jdbcType=VARCHAR}
where id = #{id,jdbcType=INTEGER}
